from xarray.core.variable import Variable


def build_grid_chunks(size: int, chunk_size: int, region: slice | None = None) -> tuple[int, ...]:
    if region is None:
        region = slice(0, size)

    start = region.start if region.start is not None else 0
    stop = region.stop if region.stop is not None else size

    # Offset of the region start within the grid
    offset = start % chunk_size

    # Size of the first chunk (partial if not aligned to grid boundary)
    first_chunk = chunk_size - offset if offset != 0 else chunk_size

    # If first chunk already covers the entire region
    region_size = stop - start
    if first_chunk >= region_size:
        return (region_size,)

    chunks = [first_chunk]
    remaining = region_size - first_chunk
    while remaining > 0:
        c = min(chunk_size, remaining)
        chunks.append(c)
        remaining -= c

    return tuple(chunks)


def _align_1d_chunks(
    v_chunks: tuple[int, ...], backend_chunks: tuple[int, ...]
) -> tuple[int, ...]:
    """Align chunks along a single dimension."""
    if len(backend_chunks) == 1:
        # Single backend chunk — no optimization needed
        return v_chunks

    # Validate that backend chunks are uniformly sized (excluding borders)
    fixed_chunk = max(backend_chunks)
    inner_chunks = backend_chunks[1:-1] if len(backend_chunks) > 2 else []
    for c in inner_chunks:
        if c != fixed_chunk:
            raise ValueError(
                "Backend chunks are not uniformly sized (excluding border chunks). "
                f"Expected {fixed_chunk}, got {c}. This is an internal error, "
                "please report it."
            )

    # Validate total sizes match
    if sum(v_chunks) != sum(backend_chunks):
        raise ValueError(
            "Total number of elements in backend chunks doesn't match the variable chunks."
        )

    # max_chunk: maximum allowed chunk size
    max_chunk = max(fixed_chunk, *v_chunks)

    # Add artificial padding to handle border chunks
    first_padded = v_chunks[0] + (fixed_chunk - backend_chunks[0])
    last_padded = v_chunks[-1] + (fixed_chunk - backend_chunks[-1])

    padded_v_chunks = [first_padded] + list(v_chunks[1:-1]) + [last_padded]

    aligned = []
    unfilled_size = 0  # remaining space in last backend chunk

    for i, v_chunk in enumerate(padded_v_chunks):
        if unfilled_size > 0:
            # Last aligned chunk is unfilled — try merging
            ideal_size = aligned[-1] + v_chunk
            if ideal_size <= max_chunk:
                # Merge: extend the last aligned chunk
                aligned[-1] = ideal_size
                unfilled_size = (fixed_chunk - ideal_size % fixed_chunk) % fixed_chunk
            else:
                # Can't merge — need to split
                # max_increase that keeps alignment
                max_increase = (max_chunk - aligned[-1]) - (
                    (max_chunk - aligned[-1] - unfilled_size) % fixed_chunk
                )
                if max_increase > 0:
                    aligned[-1] += max_increase
