    last_border_changed = aligned[-1] != last_original
    if last_border_changed and len(aligned) >= 2:
        if aligned[-1] + aligned[-2] <= max_chunk:
            aligned = aligned[:-2] + [aligned[-2] + aligned[-1]]

    return tuple(aligned)


def align_nd_chunks(
    nd_v_chunks: tuple[tuple[int, ...], ...],
    nd_backend_chunks: tuple[tuple[int, ...], ...],
) -> tuple[tuple[int, ...], ...]:
    if len(nd_v_chunks) != len(nd_backend_chunks):
        raise ValueError(
            "The number of dimensions between backend and variable chunks don't match."
        )

    for v_chunks, backend_chunks in zip(nd_v_chunks, nd_backend_chunks, strict=True):
        if sum(v_chunks) != sum(backend_chunks):
            raise ValueError(
                "Total number of elements in backend chunks doesn't match the variable chunks."
            )

    result = []
    for v_chunks, backend_chunks in zip(nd_v_chunks, nd_backend_chunks, strict=True):
        result.append(_align_1d_chunks(v_chunks, backend_chunks))

    return tuple(result)


